    const c = CL.clips[name], N = c.n, times = new Float32Array(N); for (let f = 0; f < N; f++) times[f] = f / CL.fps;
    const srcQ = S.map((b) => (c.r[b.n] ? dec(c.r[b.n], Int16Array) : null));
