    R.a.copy(J.H).addScaledVector(J.rt, s * 0.11).addScaledVector(J.up, -0.06);
    R.t.copy(J.fw).addScaledVector(J.up, 0.15);
    ik(R.a, s < 0 ? J.fL : J.fR, 0.47, 0.46, R.t, R.e, R.b);
    put('thigh', segM(m, R.a, R.e, B.thigh, B.thigh));
    put('shin', segM(m, R.e, R.b, B.shin, B.shin));
