    if (d < range + 1.3 && (arc >= 360 || d < 1.2 || Math.abs(angDiff(Math.atan2(dx, dz), player.yaw)) < half + 0.2)) { boss.hitId = id; n++; hitBoss(dmg, kb, launch, dx / (d || 1), dz / (d || 1)); }
