        if (m.anim === 'tornado' || m.anim === 'spin' || m.anim === 'rise') for (let k = 0; k < 12; k++) { const a = k / 12 * TAU; emit(p.x + Math.cos(a) * 2.5, p.y + 1 + rand(0, 1.5), p.z + Math.sin(a) * 2.5, -Math.sin(a) * 9, 2, Math.cos(a) * 9, .3, 1.2, 0x8fd0ff, 0, 2); }
        if (m.quake && last) { ring(p.x, p.z, m.range + 1, 0xffd080, 0.5); ring(p.x, p.z, m.range * 0.6, 0xffffff, 0.3); SND.land(); for (let k = 0; k < 40; k++) { const a = Math.random() * TAU, r = rand(0.5, m.range); emit(p.x + Math.cos(a) * r, 0.3, p.z + Math.sin(a) * r, Math.cos(a) * 3, rand(4, 10), Math.sin(a) * 3, rand(.4, .8), rand(.8, 1.6), 0xc8a070, 20, 1); } }
