        for (let k = 0; k < 24; k++) { const a = Math.random() * TAU; emit(p.x, 0.3, p.z, Math.cos(a) * rand(4, 9), rand(3, 7), Math.sin(a) * rand(4, 9), rand(.4, .7), rand(.8, 1.4), 0xc8a070, 18, 1); }
