  { const lx = p.x + fx * 2.5, ly = 1.2 + p.y * 0.6, lz = p.z + fz * 2.5, f = (window.clearFracS || clearFrac)(p.x, 1.6 + p.y, p.z, camera.position.x, camera.position.y, camera.position.z);
    if (f < 1) { const k = Math.max(0.22, f); camera.position.set(p.x + (camera.position.x - p.x) * k, 1.6 + p.y + (camera.position.y - 1.6 - p.y) * k + (1 - k) * 2.5, p.z + (camera.position.z - p.z) * k); }
    camera.lookAt(lx, ly, lz); }
