    gradeMusou = lerp(gradeMusou, player.st === 'musou' ? 1 : 0, Math.min(1, rdt * (player.st === 'musou' ? 8 : 3)));
    hurtFlash = Math.max(hurtFlash - rdt * 2.5, player.hp < player.max * 0.25 && play ? 0.35 + Math.sin(this.t * 6) * 0.15 : 0);
    syncVisuals(dt, rdt); stepCamera(rdt); writeParticles();
